const $=s=>document.querySelector(s);let saved;try{saved=JSON.parse(localStorage.getItem('weiter-demo')||'null')}catch{}let state=Object.assign({disease:'schlaganfall',profiles:{},country:'DE',role:'Angehörige:r',phase:0,checks:[],notes:''},saved||{});const countries={DE:'Deutschland',AT:'Österreich',CH:'Schweiz'},flags={DE:'🇩🇪',AT:'🇦🇹',CH:'🇨🇭'},phases=['Krankenhaus','Rehabilitation','Wieder zu Hause','Langfristig begleiten'];const tasks=['Gespräch mit dem Sozialdienst vereinbaren','Fragen für das Behandlungsteam sammeln','Nächste Versorgung gemeinsam planen'];const pages=[['home','⌂','Mein Überblick'],['wissen','♡','Krankheit verstehen'],['weg','↗','Mein Weg'],['hilfe','▤','Hilfe & Anträge'],['aufgaben','☑','Planer & Aufgaben'],['dokumente','▧','Dokumente'],['pflege','♧','Wenn Pflege nötig wird'],['lexikon','📖','Medizinisches Lexikon'],['verlauf','↕','Fortschritte & Rückschläge'],['kontakte','⌕','Kontakte & Versicherung']];
function save(){try{state.profiles=state.profiles||{};state.profiles[state.disease]={phase:state.phase,checks:state.checks,notes:state.notes,questions:state.questions||[],extra:state.extra||[],needs:state.needs||{}};localStorage.setItem('weiter-demo',JSON.stringify(state))}catch{}}
function syncCondition(){if(!conditions[state.disease])state.disease='schlaganfall';const c=currentCondition();phases.splice(0,phases.length,...c.phases);tasks.splice(0,tasks.length,...c.tasks);state.phase=Math.max(0,Math.min(3,Number(state.phase)||0))}
function changeCondition(id){if(!conditions[id])return;save();state.disease=id;const p=(state.profiles||{})[id]||{phase:0,checks:[],notes:'',extra:[],needs:{}};Object.assign(state,p);state.questions=Array.isArray(p.questions)?p.questions:[];state.needs=p.needs||{};syncCondition();save();render()}
function conditionPicker(){return '<div class="condition-picker"><label for="condition-main">Dein Thema</label><select id="condition-main" onchange="changeCondition(this.value)">'+conditionOptions(state.disease)+'</select><a href="#krankheiten" class="condition-browse">Alle Erkrankungen →</a></div>'}
function modal(html){$('#dialogContent').innerHTML=html;$('#dialog').showModal()}function openSettings(){modal(`<div class="eyebrow">Dein persönlicher Begleiter</div><h2>Was passt zu deiner Situation?</h2><p class="muted">Wähle ein Thema und deinen aktuellen Bedarf.</p><label class="field" for="condition">Erkrankung / Thema</label><select id="condition" onchange="updatePhaseOptions(this.value)">${conditionOptions(state.disease)}</select><label class="field" for="land">In welchem Land bist du versichert?</label><select id="land">${Object.entries(countries).map(([k,v])=>`<option value="${k}" ${state.country===k?'selected':''}>${v}</option>`).join('')}</select><button class="plain" onclick="document.getElementById(&quot;dialog&quot;).close();insuranceEditor(document.getElementById(&quot;land&quot;).value)">Krankenversicherungsnummer hinterlegen / ändern</button><label class="field" for="role">Für wen suchst du Unterstützung?</label><select id="role"><option ${state.role==='Angehörige:r'?'selected':''}>Angehörige:r</option><option ${state.role==='Selbst betroffen'?'selected':''}>Selbst betroffen</option></select><label class="field" for="phase">Wo stehst du gerade?</label><select id="phase"></select><p class="source">Jeder Verlauf ist individuell. Die Bereiche sind Orientierungshilfen und keine Pflichtabfolge.</p><button class="primary" onclick="applySettings()">Meinen Überblick anzeigen →</button>`);updatePhaseOptions(state.disease)}
function updatePhaseOptions(id){const index=id===state.disease?state.phase:((state.profiles||{})[id]?.phase||0);$('#phase').innerHTML=conditions[id].phases.map((p,i)=>`<option value="${i}" ${index===i?'selected':''}>${p}</option>`).join('')}
function applySettings(){const id=$('#condition').value,country=$('#land').value,role=$('#role').value,selectedPhase=Number($('#phase').value);changeCondition(id);state.country=country;state.role=role;state.phase=selectedPhase;journeyViews[id]=selectedPhase;save();$('#dialog').close();render()}
function emergency(){const id=state.disease;if(knowledgeDetails[id]&&!['schlaganfall','herzinfarkt','epilepsie','amnesie'].includes(id)){modal(`<div class="eyebrow">Notfallhilfe · ${currentCondition().name}</div><h2>Bei unmittelbarer Gefahr Hilfe holen.</h2><p>${knowledgeDetails[id].warning}</p><p>Bei Lebensgefahr, Bewusstlosigkeit oder schwerer Atemnot sofort den Notruf wählen.</p>${emergencyNumbers()}<p class="source">Ein Anruf wird nicht automatisch ausgelöst. Bei nicht lebensbedrohlichen neuen Beschwerden das Behandlungsteam kontaktieren.</p><a href="${currentCondition().source}" target="_blank" rel="noopener">Medizinische Informationen nachlesen ↗</a>`);return;}let message='Bei Lebensgefahr, Bewusstlosigkeit, schwerer Atemnot oder plötzlich auftretenden neurologischen Ausfällen sofort den Notruf wählen.';let link='https://gesund.bund.de/schlaganfall';if(id==='schlaganfall'||id==='amnesie')message+=' Plötzlicher Gedächtnisverlust muss dringend ärztlich abgeklärt werden; bei zusätzlichen Sprachstörungen oder Lähmungen ist sofortige Notfallhilfe nötig.';if(id==='herzinfarkt'){message='Bei Verdacht auf Herzinfarkt, etwa bei starkem Druck oder Schmerzen im Brustkorb, Atemnot oder kaltem Schweiß: sofort den Notruf wählen. Nicht auf Besserung warten.';link=conditions.herzinfarkt.source}if(id==='epilepsie'){message='Notruf bei einem ersten Anfall, einem Anfall über fünf Minuten, mehreren Anfällen hintereinander, Atemproblemen, Verletzungen oder fehlender Erholung. Vor Verletzungen schützen, nicht festhalten und nichts in den Mund stecken.';link='https://www.gesundheitsinformation.de/was-tun-wenn-jemand-einen-epileptischen-anfall-hat.html'}modal(`<div class="eyebrow">Notfallhilfe</div><h2>Bei einem Notfall sofort Hilfe holen.</h2><p>${message}</p>${emergencyNumbers()}<p>Bei Fragen zu krankheits- oder therapiebezogenen Warnzeichen bitte mit dem Behandlungsteam einen persönlichen Notfallplan vereinbaren.</p><p class="source">Ein Anruf wird nicht automatisch ausgelöst. Bitte am Telefon wählen.</p><a href="${link}" target="_blank" rel="noopener">Medizinische Informationen nachlesen ↗</a>`)}

const art=`<svg class="hero-art" viewBox="0 0 240 210" aria-hidden="true"><circle cx="120" cy="100" r="88" fill="#d5dfc6"/><path d="M39 183c50-8 13-65 75-75 32-5 28-46 74-57" fill="none" stroke="#fafbf2" stroke-width="25" stroke-linecap="round"/><path d="M40 183c50-8 13-65 75-75 32-5 28-46 74-57" fill="none" stroke="#9fb48e" stroke-width="2" stroke-dasharray="4 6"/><circle cx="114" cy="108" r="18" fill="#315d4e"/><path d="m106 108 6 6 11-12" stroke="white" stroke-width="2" fill="none"/><path d="M174 51v-24m0 0c26-9 25 19 0 12" stroke="#597a59" stroke-width="3" fill="#f6f6e9"/><path d="M47 148v-42m0 22c-28-3-24-28 0-10m0 0c25-14 28 8 0 14" stroke="#839e76" stroke-width="3" fill="#b4c5a2"/><circle cx="181" cy="157" r="5" fill="#b2c29f"/><circle cx="204" cy="114" r="3" fill="#819b73"/></svg>`;
function intro(label,title,desc){return `<div class="eyebrow">${label}</div><h1>${title}</h1><p class="muted">${desc}</p>`}function checklist(){return tasks.map((t,i)=>`<label class="check"><input type="checkbox" ${state.checks.includes(i)?'checked':''} onchange="toggle(${i})"><span class="${state.checks.includes(i)?'done':''}">${t}<small>${['Organisation · passende Ansprechperson','Vorbereitung · für dein nächstes Gespräch','Planung · gemeinsam mit dem Behandlungsteam'][i]}</small></span></label>`).join('')}function toggle(i){state.checks=state.checks.includes(i)?state.checks.filter(n=>n!==i):[...state.checks,i];save();render()}function phase(i){state.phase=i;save();render()}
function home(){return `${intro('Gut, dass du da bist.','Du musst den Weg nicht allein gehen.','Verstehen, was passiert. Wissen, was als Nächstes hilft.')}<div class="context"><span class="pill">${currentCondition().name}</span><span class="pill">${state.role}</span><span class="pill">${phases[state.phase]}</span></div><section class="hero"><div><div class="eyebrow">Dein nächster Schritt</div><h2>${currentCondition().phases[state.phase]}</h2><p>${currentCondition().steps[state.phase]}</p><button class="primary" onclick="location.hash='weg'">Meinen Weg ansehen →</button></div>${art}</section><div class="section-head"><h2>Was dir jetzt helfen kann</h2><span class="muted" style="font-size:12px">In deinem Tempo</span></div><div class="grid"><a class="card" href="#wissen"><span class="icon">♡</span><h3>${currentCondition().name} verstehen</h3><p>Was passiert im Körper? Verständliche Antworten auf erste Fragen.</p><span class="arrow">Wissen, das Orientierung gibt <b>↗</b></span></a><a class="card" href="#hilfe"><span class="icon" style="background:#f4eee0">▤</span><h3>Unterstützung finden</h3><p>Welche Hilfe kommt infrage – und an wen kannst du dich wenden?</p><span class="arrow">Für ${countries[state.country]} <b>↗</b></span></a><a class="card" href="#angehoerige"><span class="icon" style="background:#eeeaf3">♧</span><h3>Auch an dich denken</h3><p>Für Angehörige: begleiten, Unterstützung teilen und Kraft bewahren.</p><span class="arrow">Raum für deine Fragen <b>↗</b></span></a></div><div class="columns"><section class="panel"><div class="section-head" style="margin:0"><h2>Deine nächsten Aufgaben</h2><a href="#aufgaben">Alle ansehen →</a></div><p class="muted" style="font-size:12px">${state.checks.length} von 3 erledigt · Schritt für Schritt</p><div class="progress"><i style="width:${state.checks.length/3*100}%"></i></div>${checklist()}</section><section class="panel soft"><div class="eyebrow">Für dein nächstes Gespräch</div><h2 style="margin-top:17px">Jede Frage darf gestellt werden.</h2><p>„${currentCondition().questions[0]}“</p><button class="secondary" onclick="notes()">Eigene Fragen notieren ↗</button>${questionList(true)}</section></div>${careEntry()}`}
function knowledgeList(items){return '<ul class="knowledge-list">'+items.map(x=>'<li>'+x+'</li>').join('')+'</ul>'}
function knowledgeSection(id,title,content,open=false){return `<details class="knowledge-section" id="wissen-${id}" ${open?'open':''}><summary>${title}</summary><div class="knowledge-section-content">${content}</div></details>`}
function jumpKnowledge(id){const el=document.getElementById('wissen-'+id);if(!el)return;el.open=true;el.scrollIntoView({behavior:'smooth',block:'start'})}
function expandKnowledge(open){document.querySelectorAll('.knowledge-section').forEach(el=>el.open=open)}
function wissen(){const c=currentCondition(),k=knowledgeDetails[state.disease];return `${intro('Krankheit verstehen',c.name+' – verständlich erklärt.','Von ersten Anzeichen bis zum Alltag mit der Erkrankung. Lies die Abschnitte, die dir gerade wichtig sind.')}<div class="knowledge-layout"><div class="knowledge-article"><section class="panel knowledge-overview"><span class="tag">${c.group}</span><h2>Was passiert im Körper?</h2><p>${c.body}</p><p class="source">Die folgenden Informationen beschreiben typische Möglichkeiten. Sie ersetzen keine individuelle Diagnose oder Therapieplanung.</p></section><div class="knowledge-controls"><span class="source">Vertiefende Informationen</span><div><button class="plain" onclick="expandKnowledge(true)">Alle öffnen</button><button class="plain" onclick="expandKnowledge(false)">Alle schließen</button></div></div>${knowledgeSection('symptoms','Welche Symptome können auftreten?',knowledgeList(k.symptoms)+'<p class="source">Beschwerden können auch andere Ursachen haben. Aus dieser Liste lässt sich keine Diagnose ableiten.</p>',true)}${knowledgeSection('diagnosis','Wie wird die Diagnose gestellt?',knowledgeList(k.diagnosis))}${knowledgeSection('treatment','Welche Behandlungen gibt es?',knowledgeList(k.treatment)+'<p class="source">Behandlungswahl und Verfügbarkeit hängen von Befunden und persönlicher Situation ab. Medikamente nicht ohne ärztliche Absprache ändern.</p>')}${knowledgeSection('course','Wie können Verlauf und Erholung aussehen?','<p>'+k.course+'</p>')}${knowledgeSection('daily','Was ist im Alltag wichtig?',knowledgeList(k.life))}${knowledgeSection('family','Wie können Angehörige unterstützen?','<p>'+k.relatives+'</p>')}${knowledgeSection('warnings','Welche Warnzeichen sind wichtig?','<div class="knowledge-warning"><p>'+k.warning+'</p><button class="emergency" onclick="emergency()">Notfallnummern & Hinweise ↗</button></div>')}${knowledgeSection('terms','Medizinisches Lexikon zur Erkrankung','<dl class="knowledge-glossary">'+lexiconTerms(state.disease).map(([term,meaning])=>'<dt>'+term+'</dt><dd>'+meaning+'</dd>').join('')+'</dl><p><a href="#lexikon">Im Lexikon suchen →</a></p>')}<section class="panel knowledge-questions"><h2>Für dein nächstes Gespräch</h2>${knowledgeList(c.questions)}<button class="primary" onclick="notes()">Eigene Fragen festhalten →</button>${questionList(true)}</section><section class="knowledge-sources"><h3>Quellen und Aktualität</h3>${knowledgeSources(c,k).map(s=>`<p><a href="${s.url}" target="_blank" rel="noopener">${s.title} · ${c.name} ↗</a></p>`).join('')}<p class="source">Quellen am 24.10.2026 aufgerufen. Die Texte fassen wesentliche Informationen verständlich zusammen. Therapieverfügbarkeit kann zwischen Deutschland, Österreich und der Schweiz abweichen.</p></section></div><section class="panel knowledge-index"><div class="eyebrow">Gezielt nachlesen</div><h3>Was möchtest du wissen?</h3>${[['symptoms','Symptome'],['diagnosis','Diagnose'],['treatment','Behandlung'],['course','Verlauf & Erholung'],['daily','Alltag'],['family','Für Angehörige'],['warnings','Warnzeichen'],['terms','Fachbegriffe']].map(([id,label])=>`<button class="plain" onclick="jumpKnowledge('${id}')">${label} →</button>`).join('')}<hr><a href="#hilfe">Leistungen & Anträge ansehen ↗</a><a href="#krankheiten">Andere Erkrankung auswählen ↗</a></section></div>`}
function catalogCards(query=''){const search=query.toLocaleLowerCase('de').trim(),entries=Object.entries(conditions).filter(([,c])=>(c.name+' '+c.group+' '+(c.name==='COPD'?'Lunge chronisch obstruktiv':c.name==='Alzheimer-Demenz'?'Gedächtnis':'' )).toLocaleLowerCase('de').includes(search));return entries.length?entries.map(([id,c])=>`<button class="card condition-card" onclick="chooseFromCatalog('${id}')"><span class="tag">${c.group}</span><h2>${c.name}</h2><p>${c.body}</p><span class="arrow">Verstehen & begleiten <b>→</b></span></button>`).join(''):'<section class="panel"><h2>Kein passendes Thema gefunden.</h2><p>Versuche einen anderen Begriff. Die Krankheitsübersicht enthält eine begrenzte Auswahl und stellt keine Diagnose.</p></section>'}
function conditionCatalog(){return `${intro('Krankheitsübersicht',Object.keys(conditions).length+' Themen. Ein Ort für Orientierung.','Wähle eine Erkrankung aus. Informationen, Begleitphasen und Aufgaben passen sich an.')}<label class="field" for="condition-search">Erkrankung oder Bereich suchen</label><input class="condition-search" id="condition-search" type="search" placeholder="Zum Beispiel Diabetes, Lunge oder Krebs" oninput="document.querySelector('#condition-results').innerHTML=catalogCards(this.value)"><div class="grid condition-results" id="condition-results">${catalogCards()}</div>`}
function chooseFromCatalog(id){changeCondition(id);location.hash='wissen'}

let journeyViews={};
function journeyIndex(){return Number.isInteger(journeyViews[state.disease])?journeyViews[state.disease]:state.phase}
function viewJourney(index){if(!Number.isInteger(index)||index<0||index>3)return;journeyViews[state.disease]=index;render();document.getElementById('journey-content')?.scrollIntoView({behavior:'smooth',block:'start'})}
function setJourneyCurrent(index){if(!Number.isInteger(index)||index<0||index>3)return;state.phase=index;journeyViews[state.disease]=index;save();render()}
function journeyTaskKey(index,action){return 'journey:'+state.disease+':'+index+':'+action}
function journeyTaskDone(index,action){return (state.extra||[]).some(t=>t.key===journeyTaskKey(index,action)&&t.done)}
function ensureJourneyTask(index,action){const p=journeyPlan(index),key=journeyTaskKey(index,action);state.extra=state.extra||[];let t=state.extra.find(t=>t.key===key);if(!t){t={key,title:p.actions[action],done:false,journeyPhase:index,journeyAction:action};state.extra.push(t)}return t}
function toggleJourneyTask(index,action,checked){ensureJourneyTask(index,action).done=Boolean(checked);save();render()}
function saveJourneyTasks(index){for(let i=0;i<journeyPlan(index).actions.length;i++)ensureJourneyTask(index,i);save();modal('<h2>Deine nächsten Schritte sind vorgemerkt.</h2><p>Du findest sie in „Meine Aufgaben“ wieder. Bereits geklärte Punkte bleiben abgehakt.</p><button class="primary" onclick="document.querySelector(\'#dialog\').close();location.hash=\'aufgaben\'">Meine Aufgaben öffnen →</button>')}
function journeyHelp(category){helpCategory=category;location.hash='hilfe'}
function revisitJourney(index){journeyViews[state.disease]=index;location.hash='weg'}
function weg(){const c=currentCondition(),k=knowledgeDetails[state.disease],index=journeyIndex(),p=journeyPlan(index),done=p.actions.filter((_,i)=>journeyTaskDone(index,i)).length,isCurrent=index===state.phase,relative=state.role==='Angehörige:r';const sourceLinks=knowledgeSources(c,k);if(state.disease==='schlaganfall')sourceLinks.push({title:'IQWiG · Rehabilitation und Alltag',url:'https://www.gesundheitsinformation.de/schlaganfall-rehabilitation-und-rueckkehr-in-den-alltag.html'});return `${intro('Mein Weg','Nicht alles auf einmal. Deinen nächsten Schritt finden.',relative?'Du begleitest einen nahestehenden Menschen. Hier findest du Orientierung für euch beide.':'Hier findest du Orientierung für das, was dich gerade beschäftigt – und für das, was als Nächstes helfen kann.')}<div class="journey-context"><span class="pill">${c.name}</span><span class="pill">${state.role}</span><span class="journey-current">Deine Situation: ${c.phases[state.phase]}</span></div><div class="journey-layout"><section class="journey-map" aria-label="Bereiche deines Weges"><div class="eyebrow">Dein Weg im Überblick</div><ol>${c.phases.map((name,i)=>`<li class="${i===index?'viewed':''}"><button onclick="viewJourney(${i})" aria-pressed="${i===index}"><span class="journey-dot">${i+1}</span><span><strong>${name}</strong><small>${i===state.phase?'Hier stehst du gerade':i===index?'Gerade geöffnet':'Bereich ansehen'}</small></span></button></li>`).join('')}</ol><p>Du darfst Bereiche überspringen, wiederholen oder zurückgehen. Es gibt keinen festen Zeitplan für alle.</p><button class="plain" onclick="viewJourney(${state.phase})">Zu meiner aktuellen Situation →</button></section><div class="journey-main" id="journey-content"><section class="journey-hero"><div class="eyebrow">${isCurrent?'Deine aktuelle Situation':'Ein Blick in einen anderen Bereich'}</div><h2>${p.title}</h2><p>${p.warmth}</p><div class="journey-hero-footer"><span>${c.phases[index]}</span>${isCurrent?'<span class="journey-status">Von dir ausgewählt</span>':`<button class="secondary" onclick="setJourneyCurrent(${index})">Hier stehe ich gerade</button>`}</div></section><section class="panel journey-expect"><div class="eyebrow">Orientierung</div><h2>Das kann dich jetzt erwarten</h2>${knowledgeList(p.happens)}<p class="source">Was davon auf dich zutrifft, klärt dein Behandlungsteam anhand deiner persönlichen Situation.</p></section><section class="panel journey-actions"><div class="section-head" style="margin:0"><div><div class="eyebrow">Ein kleiner Schritt reicht für heute</div><h2>Was du als Nächstes tun kannst</h2></div><span class="journey-count">${done} / ${p.actions.length}</span></div><p class="muted journey-action-intro">Beginne mit dem Punkt, der für dich gerade passt. Die Reihenfolge ist ein Vorschlag.</p>${p.actions.map((text,i)=>`<label class="check"><input type="checkbox" ${journeyTaskDone(index,i)?'checked':''} onchange="toggleJourneyTask(${index},${i},this.checked)"><span class="${journeyTaskDone(index,i)?'done':''}">${text}<small>${journeyTaskDone(index,i)?'Für dich geklärt':'Noch offen – in deinem Tempo'}</small></span></label>`).join('')}<div class="journey-actions-footer"><button class="secondary" onclick="saveJourneyTasks(${index})">Schritte auf meine Aufgabenliste +</button><small>Die Häkchen zeigen organisatorische Schritte, keinen medizinischen Fortschritt.</small></div></section><div class="journey-pair"><section class="panel"><span class="icon">♧</span><h2>Du musst das nicht allein klären</h2><p class="muted">Diese Personen oder Stellen können je nach Bedarf unterstützen:</p>${knowledgeList(p.team)}<p class="source">Bezeichnungen und Angebote können je nach Land und Einrichtung abweichen.</p></section><section class="panel soft"><div class="eyebrow">Für dein nächstes Gespräch</div><h2>Diese Fragen darfst du stellen</h2>${knowledgeList(p.questions)}<button class="secondary" onclick="notes()">Meine Fragen notieren ↗</button>${questionList(true)}</section></div><details class="journey-documents"><summary>Welche Unterlagen sollte ich griffbereit haben?</summary>${knowledgeList(p.documents)}<p class="source">Als Orientierung gedacht; die zuständige Stelle sagt dir, was tatsächlich benötigt wird.</p></details><section class="journey-family"><div class="eyebrow">${relative?'Auch dein Bedarf zählt':'Gemeinsam leichter'}</div><h2>${relative?'Was dir beim Begleiten helfen kann':'Wie dein Umfeld unterstützen kann'}</h2><p>${k.relatives}</p><p>${relative?'Du darfst deine eigenen Grenzen und deinen Unterstützungsbedarf ansprechen.':'Du entscheidest, welche Hilfe du möchtest und wen du in Gespräche einbeziehst.'}</p><a href="#angehoerige">Mehr für Angehörige →</a></section><section class="panel journey-benefits"><div><div class="eyebrow">Praktische Unterstützung</div><h2>Welche Leistungen könnten helfen?</h2><p>Für ${countries[state.country]} findest du konkrete Anträge, Voraussetzungen und Unterlagen. Welche Leistung passt, hängt vom Bedarf ab.</p></div><button class="primary" onclick="journeyHelp('${p.benefitsCategory}')">Hilfe & Anträge ansehen →</button></section><details class="journey-warning"><summary>Wann sollte ich medizinische Hilfe holen?</summary><p>${k.warning}</p><button class="emergency" onclick="emergency()">Notfallnummern & Hinweise ↗</button></details><section class="panel planner-panel"><h2>Fortschritte und Rückschläge begleiten</h2><p>Auch unveränderte oder schwierige Tage dürfen notiert werden. Entlastung ist Teil des Weges.</p><a class="secondary benefit-link" href="#verlauf">Verlauf festhalten →</a><a class="plain" href="#aufgaben">Entlastung planen →</a></section><section class="journey-next"><div><div class="eyebrow">${index<3?'Schon ein wenig vorausblicken':'Der Weg darf sich verändern'}</div><h2>${index<3?c.phases[index+1]:'Du kannst jederzeit neu ansetzen.'}</h2><p>${index<3?journeyPlan(index+1).title+'. Du kannst dich schon umsehen; deine aktuelle Situation bleibt dabei gespeichert.':'Wenn sich Fragen oder Bedürfnisse ändern, schau in den passenden Bereich zurück. Du musst keinen Abschnitt „abschließen“.'}</p></div><div class="journey-nav">${index>0?`<button class="secondary" onclick="viewJourney(${index-1})">← Zurückblicken</button>`:''}${index<3?`<button class="primary" onclick="viewJourney(${index+1})">Nächsten Bereich ansehen →</button>`:`<button class="primary" onclick="viewJourney(${state.phase})">Zu meiner Situation →</button>`}</div></section><p class="source journey-sources">Grundlagen: ${sourceLinks.map(s=>`<a href="${s.url}" target="_blank" rel="noopener">${s.title} ↗</a>`).join(' · ')}<br>Quellen aufgerufen am 24.10.2026 · Planungshilfe.</p></div></div>`}

let helpCategory='all';
function currentHelp(){return relevantBenefits()}
function changeInsurer(value){if(!(insurerChoices[state.country]||[]).some(x=>x[0]===value))return;state.insurers=state.insurers||{};state.insurers[state.country]=value;save();render()}
function setNeed(key,value){if(!['status','grade',...Object.keys(needQuestions)].includes(key))return;needsFor()[key]=value;save();render()}
function benefitCard(b){const route=benefitRoute(b),match=benefitMatch(b);return `<section class="card benefit-card"><div class="route-tags"><span class="tag">${b.specific?'Erkrankungsbezogen':benefitCategories[b.category]}</span><span class="tag ${match==='review'?'tag-review':''}">${match==='review'?'Bedarf noch klären':b.specific?'Für diese Diagnose prüfbar':'Nach deinen Angaben relevant'}</span></div><h2>${b.title}</h2><p>${b.benefitText}</p><div class="benefit-condition"><strong>${match==='review'?'Wird erst bei folgendem Bedarf passend':'Wichtige Voraussetzungen'}</strong><p>${b.eligibility}</p>${match==='review'?'<small>Die dafür nötigen Angaben sind noch offen. Kein bestätigter Anspruch.</small>':''}</div><p class="benefit-authority"><strong>Wo?</strong> ${b.authority}</p><div class="route-destination"><strong>${route.kind}</strong><small>${route.specific?insurerName():externalAuthorityIds.includes(b.id)?'Zuständigkeit bleibt unabhängig von deiner Kasse':'Allgemeiner Zugang – kein eigener Kassenlink hinterlegt'}</small></div><div class="benefit-actions"><button class="primary" onclick="benefitDetail('${b.id}')">Antragsweg & Unterlagen →</button><button class="plain" onclick="addHelp('${b.id}')">Vormerken +</button></div></section>`}
function needForm(){const n=needsFor();return `<details class="needs-panel" open><summary>Deinen Bedarf ergänzen – damit die Liste genauer wird</summary><p>Beantworte nur, was du weißt. „Nein“ blendet den entsprechenden Weg aus; „Noch unklar“ ist keine Ablehnung. Auswahl und Antworten bleiben in diesem Browser.</p><label class="field" for="employment">Situation der betroffenen Person</label><select id="employment" onchange="setNeed('status',this.value)">${[['unknown','Noch unklar / keine Angabe'],['working','Im Erwerbsleben / Ausbildung / entsprechende Absicherung'],['pension','Altersrente / AHV-Alter'],['child','Kind / jugendlich']].map(([id,label])=>`<option value="${id}" ${n.status===id?'selected':''}>${label}</option>`).join('')}</select>${state.country==='DE'?`<label class="field" for="care-grade">Anerkannter Pflegegrad (nur Deutschland)</label><select id="care-grade" onchange="setNeed('grade',this.value)">${[['unknown','Noch unklar'],['none','Kein Pflegegrad'],['1','Pflegegrad 1'],['2','Pflegegrad 2'],['3','Pflegegrad 3'],['4','Pflegegrad 4'],['5','Pflegegrad 5']].map(([id,label])=>`<option value="${id}" ${(n.grade||'unknown')===id?'selected':''}>${label}</option>`).join('')}</select>`:''}<div class="needs-grid">${visibleNeedKeys().map(key=>`<label class="need-field" for="need-${key}"><span>${needQuestions[key]}</span><select id="need-${key}" onchange="setNeed('${key}',this.value)">${[['unknown','Noch unklar'],['yes','Ja / trifft zu'],['no','Nein / trifft nicht zu']].map(([id,label])=>`<option value="${id}" ${(n[key]||'unknown')===id?'selected':''}>${label}</option>`).join('')}</select></label>`).join('')}</div><p class="source">Keine automatisierte medizinische oder rechtliche Entscheidung. Weitere Voraussetzungen, etwa Versicherungszeiten, Pflegegrad und ärztliche Befunde, müssen von der zuständigen Stelle geprüft werden.</p></details>`}
function hilfe(){const country=state.country,all=benefits[country]||[],matched=currentHelp(),core=matched.filter(b=>b.specific),general=matched.filter(b=>!b.specific&&!b.drv),visible=list=>helpCategory==='all'?list:list.filter(b=>b.category===helpCategory),pending=all.filter(b=>benefitMatch(b)==='pending'),provider=selectedInsurer();return `${intro('Hilfe & Anträge','Passende Wege für deine Situation.',`${currentCondition().name} · ${countries[country]}`)}<section class="panel insurer-panel"><div><label class="field" for="insurer-select">Bei welcher Krankenversicherung bist du?</label><select id="insurer-select" onchange="changeInsurer(this.value)">${(insurerChoices[country]||[]).map(([id,label])=>`<option value="${id}" ${provider===id?'selected':''}>${label}</option>`).join('')}</select><button class="plain" onclick="insuranceEditor()">Versicherungsnummer hinterlegen / ändern</button><p class="source">${country==='DE'&&provider==='tk'?'Für deine TK sind gezielte Antrags-, Verordnungs- und Programmseiten hinterlegt. Manche Wege erfordern eine Anmeldung bei der TK oder laufen über die Praxis.':'Die Auswahl wird gespeichert. Kassenbezogene Links erscheinen nur, wenn sie recherchiert sind; sonst bleibt der allgemeine offizielle Zugang sichtbar.'}</p></div><button class="country" onclick="openSettings()">${flags[country]} ${countries[country]} ändern ▾</button></section><div class="note">Die Liste berücksichtigt Erkrankung, Bedarf und deine Angaben. <strong>Relevanz ist keine Leistungszusage.</strong> Andere Stellen wie Rentenversicherung, Versorgungsamt oder IV bleiben zuständig, auch wenn eine Krankenkasse gewählt ist.${country==='DE'&&provider==='private'?' Für Privatversicherte gelten individuelle Tarifbedingungen; gesetzliche Kassenwege werden hier ausgeblendet.':''}${country!=='DE'?' Der Ausbau krankheitsspezifischer Wege und einzelner Versicherungslinks beginnt mit TK / Deutschland. Die landesspezifischen allgemeinen Leistungen bleiben nach Bedarf filterbar.':''}</div>${needForm()}<div class="benefit-tabs" role="group" aria-label="Leistungsbereiche filtern">${Object.entries(benefitCategories).map(([id,label])=>`<button class="${helpCategory===id?'selected':''}" aria-pressed="${helpCategory===id}" onclick="helpCategory='${id}';render()">${label}</button>`).join('')}</div>${drvSection(matched.filter(b=>b.drv))}<div class="section-head"><h2>Erkrankungsbezogene Wege</h2><span class="source">${visible(core).length} Einträge</span></div><div class="benefit-grid">${visible(core).map(benefitCard).join('')||'<section class="panel"><h3>Kein eigener erkrankungsspezifischer Weg in dieser Auswahl hinterlegt.</h3><p>Viele Leistungen richten sich nach konkreten Einschränkungen statt nach dem Krankheitsnamen. Ergänze deinen Bedarf oder wähle einen anderen Leistungsbereich.</p></section>'}</div><div class="section-head"><h2>Weitere Leistungen nach deinem Bedarf</h2><span class="source">${visible(general).length} Einträge</span></div><div class="benefit-grid">${visible(general).map(benefitCard).join('')||'<section class="panel"><h3>Hier erscheinen passende allgemeine Leistungen.</h3><p>Ergänze oben beispielsweise Pflegebedarf, Arbeitsunfähigkeit oder Zuzahlungsbelastung. Es werden keine pauschalen Ansprüche aus der Diagnose abgeleitet.</p></section>'}</div>${pending.length?`<details class="pending-benefits"><summary>${pending.length} weitere Wege benötigen noch Angaben</summary><p>Diese Leistungen werden nicht als passend vorausgesetzt. Die benötigten Angaben kannst du oben ergänzen.</p><ul>${pending.map(b=>`<li><strong>${b.title}</strong><br><small>${(routeRules[b.id]?.needs||[]).map(key=>needQuestions[key]).join(' · ')||'Alters- beziehungsweise Erwerbssituation klären.'}</small></li>`).join('')}</ul></details>`:''}<p class="source">Keine vollständige Anspruchsprüfung und keine abschließende Leistungsliste. Die Angaben können besondere Einzelfälle nicht abbilden. Quellen und Links am 24.10.2026 aufgerufen. Es werden keine Anträge automatisch eingereicht.</p>`}
function benefitDetail(id,country=state.country,insurer=selectedInsurer(country)){const b=(benefits[country]||[]).find(x=>x.id===id);if(!b)return;const route=benefitRoute(b,country,insurer);modal(`<div class="eyebrow">${countries[country]} · ${b.specific?'Erkrankungsbezogener Weg':benefitCategories[b.category]}</div><h2>${b.title}</h2><section class="application-route"><span class="tag">${route.kind}</span><h3>Dein Zugang: ${route.specific?insurerName(country,insurer):'zuständige Stelle / offizieller Leistungsweg'}</h3><p>${route.note}</p><a class="primary benefit-link" href="${route.url}" target="_blank" rel="noopener">${route.label} ↗</a><p class="source">Externe Seite. Ein Login, eine regionale Auswahl oder die Mitwirkung einer Praxis kann erforderlich sein. Das Öffnen des Links stellt noch keinen Antrag.</p></section><h3>Das kannst du beantragen / erhalten</h3><p>${b.benefitText}</p><h3>Welche Voraussetzungen müssen vorliegen?</h3><p>${b.eligibility}</p><p class="source">Wichtige Bedingungen als Auszug. Deine Auswahl in dieser App ist keine Bewilligung.</p><h3>Zuständige Stelle</h3><p>${b.authority}</p><h3>Typische Unterlagen</h3><ul>${b.documents.map(x=>'<li>'+x+'</li>').join('')}</ul><h3>So gehst du vor</h3><ol>${applicationSteps(b,country,insurer).map(x=>'<li>'+x+'</li>').join('')}</ol><div class="note">${b.important}</div><button class="secondary" onclick="remindBenefit('${b.id}','${country}','${insurer}')">Fristerinnerung im Planer +</button><button class="secondary" onclick="document.querySelector('#dialog').close();addHelp('${b.id}','${country}','${insurer}')">Weg auf meine Aufgabenliste setzen +</button><p class="source">Quellen: <a href="${b.source}" target="_blank" rel="noopener">Leistung und Voraussetzungen ↗</a>${b.extraSource?` · <a href="${b.extraSource}" target="_blank" rel="noopener">Weitere offizielle Informationen ↗</a>`:''}<br>Am ${b.drv?'25.10.2026':'24.10.2026'} aufgerufen</p>`)}
function addHelp(id,country=state.country,insurer=selectedInsurer(country)){const list=benefits[country]||[],b=typeof id==='number'?list[id]:list.find(x=>x.id===id);if(!b)return;state.extra=state.extra||[];const route=benefitRoute(b,country,insurer),key=country+':'+b.id+':'+insurer,title=b.title+' · '+countries[country]+(route.specific?' · '+insurerName(country,insurer):'');if(!state.extra.some(t=>t.key===key))state.extra.push({key,title,done:false,benefitId:b.id,country,insurer});save();modal('<h2>Als Aufgabe vorgemerkt.</h2><p>Die gewählte Versicherung und der Antragsweg bleiben bei dieser Aufgabe gespeichert. Es wurde kein Antrag eingereicht.</p><button class="primary" onclick="document.querySelector(\'#dialog\').close();location.hash=\'aufgaben\'">Zur Aufgabenliste →</button>')}

function aufgaben(){return `${intro('Planer & Aufgaben','Organisation und Entlastung gemeinsam planen.','Sammle nächste Schritte und hake ab, was du schon geklärt hast.')}<section class="panel article"><p class="muted">${state.checks.length} von 3 Basisaufgaben erledigt</p><div class="progress"><i style="width:${state.checks.length/3*100}%"></i></div>${checklist()}${(state.extra||[]).map((t,i)=>`<label class="check"><input type="checkbox" ${t.done?'checked':''} onchange="state.extra[${i}].done=this.checked;save();render()"><span class="${t.done?'done':''}">${t.title}<small>${t.journeyPhase!==undefined?'Aus Mein Weg · '+phases[t.journeyPhase]:t.careTask?'Aus Wenn Pflege nötig wird':'Aus Hilfe & Anträge hinzugefügt'}</small>${t.journeyPhase!==undefined?`<button class="task-detail" onclick="event.preventDefault();revisitJourney(${t.journeyPhase})">Bereich in Mein Weg öffnen ↗</button>`:''}${t.benefitId?`<button class="task-detail" onclick="event.preventDefault();benefitDetail('${t.benefitId}','${t.country}','${t.insurer||selectedInsurer(t.country)}')">Antragsweg wieder öffnen ↗</button>`:''}</span></label>`).join('')}<p><button class="secondary" onclick="notes()">Neue Frage notieren +</button></p><p class="source">Aufgaben und Notizen bleiben lokal in diesem Browser. </p><button class="plain" onclick="resetDemo()">Aufgaben und Fragen zurücksetzen</button></section>${plannerPanel()}`}
function escapeQuestion(value){return String(value).replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]))}
function ensureQuestions(){if(!Array.isArray(state.questions))state.questions=[];if(typeof state.notes==='string'&&state.notes.trim()){state.questions.push({text:state.notes.trim()});state.notes='';save()}return state.questions}
function questionList(embedded=false){const questions=ensureQuestions();if(!questions.length)return '';const list='<ul>'+questions.map((q,i)=>'<li><p>'+escapeQuestion(q.text)+'</p><div class="question-actions"><button class="plain" onclick="notes('+i+')" aria-label="Frage '+(i+1)+' bearbeiten">Bearbeiten</button><button class="plain question-delete" onclick="deleteQuestion('+i+')" aria-label="Frage '+(i+1)+' löschen">Löschen</button></div></li>').join('')+'</ul><p class="source">Für dieses Thema in diesem Browser gespeichert. Erledigte Fragen kannst du einzeln löschen.</p>';return embedded?'<div class="saved-questions embedded-questions" aria-labelledby="saved-questions-title"><h3 id="saved-questions-title">Meine notierten Fragen</h3>'+list+'</div>':'<section class="panel soft saved-questions" aria-labelledby="saved-questions-title"><div class="section-head"><h2 id="saved-questions-title">Meine notierten Fragen</h2><button class="secondary" onclick="notes()">Neue Frage +</button></div>'+list+'</section>'}

function notes(index=null){const editing=Number.isInteger(index),questions=ensureQuestions();if(editing&&!questions[index])return;modal('<h2>'+(editing?'Notiz bearbeiten':'Neue Frage notieren')+'</h2><p class="muted">'+(editing?'Passe deine gespeicherte Frage oder Notiz an.':'Jede gespeicherte Frage erscheint zusätzlich in deiner Fragenliste.')+'</p><form onsubmit="event.preventDefault();saveQuestion('+(editing?index:'null')+')"><label class="field" for="notes">'+(editing?'Deine Frage oder Notiz':'Deine neue Frage')+'</label><textarea id="notes" required placeholder="Zum Beispiel: Wer organisiert die weitere Versorgung?"></textarea><p id="question-error" role="status"></p><p class="source">Speicherung lokal in diesem Browser. </p><div class="note-editor-actions"><button class="primary" type="submit">'+(editing?'Änderungen speichern':'Frage speichern')+'</button><button class="secondary" type="button" onclick="document.getElementById(&quot;dialog&quot;).close()">Abbrechen</button></div></form>');$('#notes').value=editing?questions[index].text:''}
function saveQuestion(index=null){const text=$('#notes').value.trim();if(!text){$('#question-error').textContent='Bitte schreibe zuerst eine Frage oder Notiz auf.';return}const questions=ensureQuestions();if(Number.isInteger(index)){if(!questions[index])return;questions[index]={...questions[index],text}}else questions.push({text});save();$('#dialog').close();render()}

function deleteQuestion(index){const questions=ensureQuestions();if(!Number.isInteger(index)||index<0||index>=questions.length)return;questions.splice(index,1);save();render()}

function resetDemo(){modal('<h2>Aufgaben und Fragen zurücksetzen?</h2><p>Die lokal gespeicherten Aufgaben und Notizen werden entfernt.</p><button class="primary" onclick="state.checks=[];state.extra=[];state.notes=\'\';state.questions=[];save();document.querySelector(\'#dialog\').close();render()">Eingaben entfernen</button>')}
function angehoerige(){return `${intro('Für Angehörige','Auch du brauchst Unterstützung.','Begleiten kann viel Kraft kosten. Du darfst Hilfe annehmen.')}<section class="panel article"><h2>Gemeinsam statt alles allein</h2><p>Besprich mit der betroffenen Person, welche Unterstützung sie möchte. Frage das Behandlungsteam, wie du sinnvoll helfen kannst.</p><details open><summary>Unterstützung im Umfeld verteilen</summary><p>Wer übernimmt Gespräche, wer Besorgungen, wer regelmäßige Besuche? Konkrete Absprachen können den Alltag übersichtlicher machen.</p></details><details><summary>Eigene Fragen ernst nehmen</summary><p>Notiere, was dich beschäftigt. Sprich beim nächsten Termin auch an, welche Unterstützung und Beratung du selbst benötigst.</p></details><button class="primary" onclick="notes()">Meine Fragen festhalten →</button></section>`}
function render(){syncCondition();const page=location.hash.slice(1)||'home';$('#country').textContent=flags[state.country];$('#country').title='Land auswählen: '+countries[state.country];$('#country').ariaLabel='Land auswählen, aktuell '+countries[state.country];$('#nav').innerHTML=pages.map(([id,icon,title])=>`<a href="#${id}" class="${page===id?'active':''}"><span>${icon}</span>${title}</a>`).join('');$('#main').innerHTML=conditionPicker()+deadlineBanner()+({home,wissen,weg,hilfe,aufgaben,angehoerige,dokumente:documentLibrary,pflege:careGuide,lexikon:lexiconPage,verlauf:progressPage,kontakte:contactsPage,krankheiten:conditionCatalog}[page]||home)()+(['home','wissen','weg','dokumente'].includes(page)||!pages.some(([id])=>id===page)&&!['angehoerige','krankheiten'].includes(page)?'':questionList())}window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0)});render();

function openMenu(){const drawer=document.getElementById('menu-drawer');if(drawer.open)return;document.getElementById('menu-toggle').setAttribute('aria-expanded','true');document.body.classList.add('menu-open');drawer.showModal()}
function menuClosed(){document.getElementById('menu-toggle').setAttribute('aria-expanded','false');document.body.classList.remove('menu-open')}
function closeMenu(){const drawer=document.getElementById('menu-drawer');if(drawer.open)drawer.close();menuClosed()}


function emergencyNumbers(){return '<section class="emergency-number-block"><h3>112 · Europaweiter Notruf</h3><p>Bei Lebensgefahr oder schweren Notfällen. Kostenlos in der gesamten EU erreichbar, auch in der Schweiz nutzbar.</p><p class="source">Zusätzlich direkt zur Rettung: Österreich 144 · Schweiz 144.</p><h3>116117 · Ärztlicher Bereitschaftsdienst</h3><p><strong>Deutschland:</strong> Für dringende, nicht lebensbedrohliche Beschwerden, wenn die Arztpraxis geschlossen ist und die Behandlung nicht bis zur nächsten Sprechzeit warten kann. Kostenlos und rund um die Uhr erreichbar.</p><p><strong>Bei Verdacht auf Herzinfarkt, Schlaganfall oder anderer Lebensgefahr sofort 112 wählen.</strong></p><p class="source">116117 ist hier als Angebot für Deutschland aufgeführt, nicht als europaweit einheitlich verfügbarer Dienst. Entscheidend ist dein aktueller Aufenthaltsort.</p><p class="source">Offizielle Informationen: <a href="https://digital-strategy.ec.europa.eu/de/policies/112" target="_blank" rel="noopener">EU-Notruf 112</a> · <a href="https://www.116117.de/de/aerztlicher-bereitschaftsdienst.php" target="_blank" rel="noopener">Bereitschaftsdienst 116117</a></p></section>'}
function careEntry(){return '<section class="panel care-entry"><div><div class="eyebrow">Wenn der Alltag mehr Hilfe braucht</div><h2>Was passiert, wenn Pflege nötig wird?</h2><p>Erste Schritte, passende Versorgung und Entlastung für Angehörige.</p></div><a class="primary benefit-link" href="#pflege">Orientierung zur Pflege →</a></section>'}
function careCountryInfo(){return {
DE:{title:'Deutschland · Pflegegrad und Pflegeversicherung',intro:'Leistungen bei der Pflegekasse beantragen; privat Versicherte wenden sich an ihre private Pflegepflichtversicherung. Eine Diagnose allein bestimmt keinen Pflegegrad.',steps:['Pflegeberatung oder Pflegestützpunkt kontaktieren und Pflegeleistungen beantragen; eine bevollmächtigte Person kann unterstützen.','Begutachtung vorbereiten: Welche Alltagstätigkeiten gelingen nur mit Hilfe? Befunde und konkrete Beispiele bereithalten.','Die Begutachtung beurteilt den Unterstützungsbedarf; anschließend entscheidet die Versicherung und schickt einen Bescheid.','Bescheid und Gutachten prüfen, Versorgungsplan besprechen und bei Unstimmigkeiten die Rechtsbehelfsbelehrung beachten.','Pflegedienst, private Unterstützung oder Einrichtung organisieren; bei verändertem Bedarf eine erneute Prüfung ansprechen.'],funding:'Pflegegeld, Pflegesachleistungen oder Kombinationen kommen je nach Voraussetzungen infrage. Entlastungsleistungen, Tagespflege, Ersatz- oder Kurzzeitpflege und Hilfsmittel gesondert prüfen. Die Pflegeversicherung deckt nicht alle Kosten; bei Finanzierungslücken Sozialberatung zu weiteren Hilfen nutzen.',contact:'Pflegekasse / private Pflegepflichtversicherung und Pflegeberatung; im Krankenhaus zusätzlich Sozialdienst und Entlassmanagement.',sources:[['BMG · Antrag und Pflegeberatung','https://www.bundesgesundheitsministerium.de/themen/pflege/online-ratgeber-pflege/pflegebeduerftig-was-nun'],['BMG · Pflege zu Hause','https://www.bundesgesundheitsministerium.de/pflege-zu-hause']]},
AT:{title:'Österreich · Pflegegeld und regionale Angebote',intro:'Pflegegeld beim zuständigen Pensions- beziehungsweise Versicherungsträger beantragen. Für die Organisation mobiler Dienste und Einrichtungen sind auch Land und Gemeinde wichtige Anlaufstellen.',steps:['Zuständigen Träger erfragen und Pflegegeld oder eine Erhöhung beantragen; der Antrag ist auch formlos möglich.','Aktuelle Befunde und eine Beschreibung der notwendigen Hilfe zusammenstellen.','Beim angekündigten Hausbesuch wird der Pflegebedarf begutachtet. Eine gewünschte Vertrauensperson kann unterstützen.','Bescheid prüfen: Er nennt die Entscheidung über die Pflegegeldstufe. Bei Unstimmigkeiten rechtzeitig Beratung zum Rechtsmittel einholen.','Mobile Betreuung, Pflege zu Hause oder eine Einrichtung mit regionaler Beratung planen und Finanzierung klären.'],funding:'Pflegegeld ist ein Beitrag zu pflegebedingten Aufwendungen und übernimmt nicht automatisch alle Kosten. Preise, Förderungen und Eigenanteile für Dienste oder Heime mit der zuständigen Landes- oder Gemeindestelle klären.',contact:'Zuständiger Pensions-/Versicherungsträger sowie Pflegeberatung von Land oder Gemeinde.',sources:[['Österreich.gv.at · Pflegegeld beantragen','https://www.oesterreich.gv.at/de/themen/pflege/4/1/Seite.360517'],['Pensionsversicherung · Pflegegeld','https://www.pv.at/web/pflegegeld']]},
CH:{title:'Schweiz · Pflegebedarf, Spitex und Finanzierung',intro:'Pflegebedarf durch einen zugelassenen Anbieter abklären lassen. Krankenversicherung und kantonale beziehungsweise kommunale Stellen sind an der Finanzierung beteiligt.',steps:['Hausarztpraxis, zugelassene Spitex oder regionale Beratungsstelle kontaktieren.','Pflegebedarf und gegebenenfalls ärztliche Anordnung klären; Behandlungspflege erfordert eine ärztliche Anordnung.','Versorgung zu Hause oder im Heim vereinbaren und Beiträge sowie persönliche Kosten schriftlich klären.','Bei dauerhafter Hilfe im Alltag einen möglichen Anspruch auf Hilflosenentschädigung bei der zuständigen IV-/AHV-Stelle abklären.','Bei Finanzierungslücken Beratung zu Ergänzungsleistungen und kantonalen Unterstützungen einholen.'],funding:'Die Grundversicherung leistet Beiträge an anerkannte Pflege. Betreuung, Hauswirtschaft sowie Unterkunft und Verpflegung sind davon zu unterscheiden. Kostenbeteiligung und Restfinanzierung hängen von den geltenden Regeln ab.',contact:'Zugelassene Spitex / Pflegefachperson, Krankenversicherung und zuständige kantonale oder kommunale Stelle.',sources:[['BAG · Pflegeleistungen','https://www.bag.admin.ch/de/krankenversicherung-pflegeleistungen'],['BSV · Hilflosenentschädigung','https://www.bsv.admin.ch/de/hilflosenentschaedigung']]}
}[state.country]}
function careGuide(){const c=careCountryInfo();return `${intro('Wenn Pflege nötig wird','Du musst die Pflege nicht allein organisieren.','Ob plötzlich nach einer Erkrankung oder schrittweise: Gemeinsam klären, welche Hilfe jetzt gebraucht wird.')}<section class="panel"><h2>Was bedeutet Pflegebedürftigkeit?</h2><p>Ein Mensch braucht regelmäßig Unterstützung, etwa beim Waschen, Anziehen, Essen, Bewegen oder bei der Orientierung. Auch kognitive und psychische Einschränkungen können Hilfebedarf verursachen. Umfang und Dauer werden individuell beurteilt.</p><p>Pflegebedarf bedeutet nicht automatisch einen Umzug ins Heim. Wünsche der betroffenen Person, sichere Versorgung und die Kräfte der Angehörigen gehören gemeinsam in die Planung.</p></section><section class="note"><strong>Schon im Krankenhaus ansprechen:</strong> Wenn die Versorgung zu Hause noch ungeklärt ist, vor der Entlassung mit dem zuständigen Team planen. Benötigte Pflege, Medikamente, Hilfsmittel und erreichbare Kontakte besprechen. Bei unmittelbarer Gefahr die Notfallhilfe nutzen.</section><section class="panel care-country"><div class="benefit-top"><h2>${c.title}</h2><button class="country" onclick="openSettings()">${flags[state.country]} Land ändern</button></div><p>${c.intro}</p><ol class="care-steps">${c.steps.map(step=>`<li>${step}</li>`).join('')}</ol><h3>Wer hilft beim Organisieren?</h3><p>${c.contact}</p><h3>Was muss zur Finanzierung geklärt werden?</h3><p>${c.funding}</p><button class="primary" onclick="helpCategory='pflege';location.hash='hilfe'">Pflegeleistungen & Anträge ansehen →</button><p class="source">Unter Hilfe & Anträge deinen Bedarf ergänzen. Es werden keine Pflegebedürftigkeit, Einstufung oder Leistungsansprüche automatisch angenommen.</p></section><div class="section-head"><h2>Welche Versorgung passt zu euch?</h2></div><div class="benefit-grid"><section class="panel"><h3>Zu Hause mit Unterstützung</h3><p>Private Hilfe und professionelle Dienste nach Bedarf kombinieren. Klären: Wer übernimmt Körperpflege, Mahlzeiten, Medikamente und Nächte? Angehörige müssen nicht sämtliche Aufgaben selbst übernehmen.</p></section><section class="panel"><h3>Entlastung am Tag oder für eine Übergangszeit</h3><p>Regionale Tagesangebote, vorübergehende stationäre Versorgung oder Vertretung anfragen. Verfügbarkeit, Aufnahmebedingungen und Kosten vorab klären; Leistungsnamen unterscheiden sich je nach Land.</p></section><section class="panel"><h3>Dauerhafte Versorgung im Pflegeheim</h3><p>Wenn die gewünschte und sichere Versorgung zu Hause nicht gelingt, Einrichtungen vergleichen. Pflegeangebot, freie Plätze, Vertragsbedingungen und sämtliche Eigenkosten gemeinsam besprechen.</p></section><section class="panel soft"><h3>Auch Angehörige brauchen Unterstützung</h3><p>Feste Pausen, eine Vertretung und klare Aufgabenverteilung vereinbaren. Überforderung früh ansprechen. Pflegeberatung und Schulung nutzen; Hilfe anzunehmen ist kein Versagen.</p></section></div><section class="panel care-country"><h2>Diese Unterlagen helfen beim nächsten Gespräch</h2>${knowledgeList(['Arztbriefe, Entlassungsunterlagen und aktueller Medikamentenplan','Notizen zum konkreten Hilfebedarf – auch nachts und an schwierigen Tagen','Versicherungsangaben und bereits vorhandene Bescheide','Vollmacht, soweit eine Vertretung erforderlich und wirksam eingerichtet ist'])}<a class="secondary benefit-link" href="#dokumente">Dokumente ablegen →</a><button class="plain" onclick="notes()">Eigene Fragen notieren</button></section><section class="panel care-country"><h2>Die nächsten Schritte vormerken</h2><p>Du kannst diese organisatorischen Aufgaben zu deiner Liste für ${escapeQuestion(currentCondition().name)} hinzufügen.</p><button class="secondary" onclick="addCareTasks()">Pflege-Schritte auf meine Aufgabenliste +</button></section><p class="source">Offizielle Grundlagen für ${countries[state.country]}: ${c.sources.map(([title,url])=>`<a href="${url}" target="_blank" rel="noopener">${title} ↗</a>`).join(' · ')}<br>Zum Übergang aus dem Krankenhaus: <a href="https://gesund.bund.de/entlassung-aus-dem-krankenhaus" target="_blank" rel="noopener">gesund.bund.de · Entlassung</a> (Deutschland). Aufgerufen am 25.10.2026. Orientierung, keine individuelle Einstufung oder Leistungszusage.</p>`}
function addCareTasks(){state.extra=state.extra||[];for(const [i,title] of ['Pflegeberatung und feste Ansprechperson kontaktieren','Notwendige Hilfe im Alltag beschreiben','Antrag beziehungsweise Bedarfsabklärung im gewählten Land klären','Versorgung und persönliche Kosten gemeinsam planen','Vertretung und Entlastung für Angehörige organisieren'].entries()){const key='care:'+state.country+':'+i;if(!state.extra.some(t=>t.key===key))state.extra.push({key,title,done:false,careTask:true,country:state.country})}save();modal('<h2>Pflege-Schritte vorgemerkt.</h2><p>Die Aufgaben stehen unter „Meine Aufgaben“. Bereits gespeicherte Schritte wurden nicht doppelt angelegt.</p><button class="primary" onclick="document.getElementById(&quot;dialog&quot;).close();location.hash=\'aufgaben\'">Aufgaben ansehen →</button>')}

function dismissStartup(){const screen=document.getElementById("startup-screen");if(!screen)return;screen.classList.add("startup-hidden");setTimeout(()=>screen.remove(),300)}
function initializeStartup(){const screen=document.getElementById('startup-screen');if(!screen)return;let seen=window.gutBegleitetStarted===true;try{seen=seen||sessionStorage.getItem('gut-begleitet-started')==='1';sessionStorage.setItem('gut-begleitet-started','1')}catch{}window.gutBegleitetStarted=true;if(seen){screen.remove();return}screen.hidden=false;setTimeout(dismissStartup,900)}
if(typeof setTimeout==='function')initializeStartup();
